package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// chdirToConfig 把工作目录切到临时目录，并按 content 写 config/thresholds.json
// （content 为 nil 表示不写文件，用于「文件不存在」的场景）。
// 测试结束时会恢复原来的工作目录。
func chdirToConfig(t *testing.T, content []byte) {
	t.Helper()
	dir := t.TempDir()
	if content != nil {
		configDir := filepath.Join(dir, "config")
		if err := os.MkdirAll(configDir, 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(configDir, "thresholds.json"), content, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	old, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := os.Chdir(old); err != nil {
			t.Fatal(err)
		}
	})
}

func TestLowStockThresholdReadsConfig(t *testing.T) {
	chdirToConfig(t, []byte(`{"beijing": 2, "shanghai": 8}`))

	if got := LowStockThreshold("beijing"); got != 2 {
		t.Fatalf("配置了的仓库应使用自己的阈值，得到 %d", got)
	}
	if got := LowStockThreshold("shanghai"); got != 8 {
		t.Fatalf("配置了的仓库应使用自己的阈值，得到 %d", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("没配置的仓库应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestLowStockThresholdFallsBack(t *testing.T) {
	cases := []struct {
		name    string
		content []byte
	}{
		{"文件不存在", nil},
		{"空文件", []byte("")},
		{"不是 JSON", []byte("not json")},
		{"不是 JSON 对象", []byte("[1, 2, 3]")},
		{"JSON 是 null", []byte("null")},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			chdirToConfig(t, tc.content)
			if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
				t.Fatalf("应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
			}
		})
	}
}

