// LowStockWarehouses 返回 stock 里所有低库存的仓库，数量升序；数量相同时按仓库名升序。
func LowStockWarehouses(stock map[string]int) []string {
	type lowStock struct {
		warehouse string
		quantity  int
	}
	low := make([]lowStock, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, lowStock{warehouse, quantity})
		}
	}
	sort.Slice(low, func(i, j int) bool {
		if low[i].quantity != low[j].quantity {
			return low[i].quantity < low[j].quantity
		}
		return low[i].warehouse < low[j].warehouse
	})
	warehouses := make([]string, len(low))
	for i, entry := range low {
		warehouses[i] = entry.warehouse
	}
	return warehouses
}
```

