package inventory

import (
	"fmt"
	"reflect"
	"testing"
)

func TestLowStockReportFormatAndOrder(t *testing.T) {
	chdirToConfig(t, nil)

	stock := map[string]int{
		"xian":     3,
		"wuhan":    1,
		"beijing":  2,
		"chengdu":  2,
		"shanghai": 9, // 不低库存
	}
	got := LowStockReport(stock)
	want := []string{"wuhan=1", "beijing=2", "chengdu=2", "xian=3"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockReport = %v, 期望 %v", got, want)
	}
}

func TestLowStockReportMatchesWarehouseOrder(t *testing.T) {
	chdirToConfig(t, []byte(`{"beijing": 4}`))

	stock := map[string]int{
		"beijing": 3,
		"wuhan":   1,
		"xian":    2,
		"chengdu": 8,
	}
	warehouses := LowStockWarehouses(stock)
	report := LowStockReport(stock)
	if len(report) != len(warehouses) {
		t.Fatalf("报告长度 %d 与仓库数 %d 不一致", len(report), len(warehouses))
	}
	for i, warehouse := range warehouses {
		want := fmt.Sprintf("%s=%d", warehouse, stock[warehouse])
		if report[i] != want {
			t.Fatalf("report[%d] = %q, 期望 %q", i, report[i], want)
		}
	}
}

func TestLowStockReportEmpty(t *testing.T) {
	chdirToConfig(t, nil)
	if got := LowStockReport(map[string]int{}); len(got) != 0 {
		t.Fatalf("空库存应当是空报告，得到 %v", got)
	}
}
